sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float streaks;
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453);}half4 effectMain(float2 coord){half4 c=image.eval(coord);float x=floor(coord.x/size.x*streaks);float y=fract(coord.y/size.y+phase+hash(float2(x,1.0)));float streak=step(0.965,y)*step(0.3,hash(float2(x,2.0)));return half4(clamp(c.rgb+half(streak*amount)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
